<div class="mb-3"><a href="<?= url('admin/promociones/nuevo') ?>" class="btn btn-mi"><i class="bi bi-plus-lg"></i> Nueva promoción</a></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Promoción</th><th>Descuento</th><th>Vigencia</th><th>Productos</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody>
<?php foreach ($promos as $p): $vig = (int) $p['vigente'] === 1; $venc = $p['fecha_fin'] < date('Y-m-d'); ?><tr><td><b><?= e($p['nombre']) ?></b></td><td><span class="badge bg-mi"><?= (int) $p['porcentaje_descuento'] ?>%</span></td>
<td><?= fecha($p['fecha_inicio']) ?> → <?= fecha($p['fecha_fin']) ?></td><td><?= (int) $p['productos'] ?></td>
<td><?php if ($vig): ?><span class="badge text-bg-success">Vigente</span><?php elseif ($p['estado'] === 'inactiva'): ?><span class="badge text-bg-secondary">Inactiva</span><?php elseif ($venc): ?><span class="badge text-bg-dark">Vencida</span><?php else: ?><span class="badge text-bg-info">Programada</span><?php endif; ?></td>
<td class="text-end"><div class="d-inline-flex gap-1"><a class="btn btn-sm btn-outline-mi" href="<?= url('admin/promociones/' . (int) $p['id_promocion'] . '/editar') ?>"><i class="bi bi-pencil"></i></a>
<form method="post" action="<?= url('admin/promociones/' . (int) $p['id_promocion'] . '/estado') ?>"><?= csrf_field() ?><input type="hidden" name="estado" value="<?= $p['estado'] === 'activa' ? 'inactiva' : 'activa' ?>"><button class="btn btn-sm btn-outline-secondary"><?= $p['estado'] === 'activa' ? 'Desactivar' : 'Activar' ?></button></form>
<form method="post" action="<?= url('admin/promociones/' . (int) $p['id_promocion'] . '/eliminar') ?>" onsubmit="return confirm('¿Eliminar esta promoción?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach; ?>
<?php if (!$promos): ?><tr><td colspan="6" class="text-center text-muted py-4">Aún no hay promociones. ¡Crea la primera!</td></tr><?php endif; ?></tbody></table></div></div>
